<?php require_once __DIR__.'/lib/bootstrap.php'; requestMethod('GET'); $rows=db()->products(); $difficulty=['facil'=>'Iniciación','media'=>'Media','dificil'=>'Experta']; $out=[]; foreach($rows as $p){$min=(int)$p['jugadores_min'];$max=(int)$p['jugadores_max'];$players=$min===$max?(string)$min:$min.'-'.$max;$filters=[];if($min<=1)$filters[]='solo';if($max>=2&&$min<=3)$filters[]='small';if($max>=4)$filters[]='group';$out[]=['id'=>(string)$p['id'],'title'=>$p['nombre'],'subtitle'=>$p['subtitulo'],'category'=>trim(explode(' · ',(string)($p['categorias']??''))[0]),'players'=>$players,'playerFilter'=>$filters,'difficulty'=>$difficulty[(string)$p['dificultad']]??(string)$p['dificultad'],'duration'=>$p['duracion'],'origin'=>($p['origenes'] ?? ''),'author'=>$p['autor'],'price'=>(float)$p['precio'],'image'=>$p['imagen'],'description'=>$p['descripcion'],'mechanics'=>$p['mecanicas'],'language'=>$p['idioma'],'parentId'=>$p['producto_padre_id']!==null?(string)$p['producto_padre_id']:null,'stock'=>(int)$p['stock'],'tone'=>'#1c1c1c','text'=>'#ffffff','symbol'=>'◆'];} apiRespond(['products'=>$out]);
